module serial2parallel(
    input clk, 
    input rst_n, 
    input din_serial, 
    input din_valid,
    output reg [7:0] dout_parallel, 
    output reg dout_valid
);
    localparam MAX_COUNT = 4'd8;

    reg [3:0] cnt;
    reg valid_reg;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            cnt <= 4'b0;
            valid_reg <= 1'b0;
        end else begin
            if(din_valid && cnt == MAX_COUNT) begin
                cnt <= 4'b0;
                valid_reg <= 1'b1;
            end else if(din_valid) begin
                cnt <= cnt + 1;
                valid_reg <= 1'b0;
            end else begin
                cnt <= cnt;
                valid_reg <= 1'b0;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            dout_parallel <= 8'b0;
        end else begin
            if(cnt >= 4'd1 && cnt <= MAX_COUNT) begin
                dout_parallel[cnt-1] <= din_serial;
            end else begin
                dout_parallel <= dout_parallel;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            dout_valid <= 1'b0;
        end else begin
            dout_valid <= valid_reg;
        end
    end
endmodule
